<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
final class InspectionFormsService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly SiteAccessService $access) {}
    private function definition(mixed $fields): array {
        if(!is_array($fields)||!array_is_list($fields)||count($fields)<1||count($fields)>30)throw HttpException::unprocessable('Create between one and 30 inspection fields.');$seen=[];$out=[];
        foreach($fields as$f){if(!is_array($f))throw HttpException::unprocessable('Invalid inspection field.');$this->fields($f,['key','label','type','required','photo_required','followup_on_fail']);$key=$this->text($f['key']??null,60);if(!preg_match('/^[a-z][a-z0-9_]*$/D',$key)||isset($seen[$key])||!in_array($f['type']??null,['PASS_FAIL','CHECK','TEXT','NUMBER'],true))throw HttpException::unprocessable('Use unique field keys and a supported field type.');foreach(['required','photo_required','followup_on_fail']as$flag)if(!is_bool($f[$flag]??null))throw HttpException::unprocessable('Field requirements must be boolean.');if($f['followup_on_fail']&&!in_array($f['type'],['PASS_FAIL','CHECK'],true))throw HttpException::unprocessable('Failure follow-ups apply to pass/fail or check fields.');$seen[$key]=true;$out[]=['key'=>$key,'label'=>$this->text($f['label']??null,150),'type'=>$f['type'],'required'=>$f['required'],'photo_required'=>$f['photo_required'],'followup_on_fail'=>$f['followup_on_fail']];}return $out;
    }
    public function templates(array $input): array {$this->fields($input,['site_id']);$site=$this->access->requireSite($input['site_id']??null);return $this->db->fetchAll('SELECT f.* FROM inspection_form_versions f WHERE f.company_id=:company AND f.site_id=:site AND NOT EXISTS(SELECT 1 FROM inspection_form_versions newer WHERE newer.company_id=f.company_id AND newer.site_id=f.site_id AND newer.form_code=f.form_code AND newer.revision>f.revision) ORDER BY f.title',['company'=>$this->company(),'site'=>$site['site_id']]);}
    public function publish(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['site_id','form_code','expected_revision','title','fields']);$site=$this->access->requireSite($input['site_id']??null);$code=strtoupper($this->text($input['form_code']??null,60));if(!preg_match('/^[A-Z0-9_-]+$/D',$code))throw HttpException::unprocessable('Use letters, digits, hyphens or underscores for the form code.');$old=$this->db->fetch('SELECT revision FROM inspection_form_versions WHERE company_id=:company AND site_id=:site AND form_code=:code ORDER BY revision DESC LIMIT 1',['company'=>$this->company(),'site'=>$site['site_id'],'code'=>$code]);$revision=(int)($old['revision']??0);if($this->number($input['expected_revision']??null,0)!==$revision)throw HttpException::conflict('Form changed. Refresh its latest version.');$fields=$this->definition($input['fields']??null);$this->db->execute('INSERT INTO inspection_form_versions(company_id,site_id,form_code,revision,title,fields_json,published_by_user_id,published_at) VALUES(:company,:site,:code,:revision,:title,:fields,:actor,:now)',['company'=>$this->company(),'site'=>$site['site_id'],'code'=>$code,'revision'=>$revision+1,'title'=>$this->text($input['title']??null,150),'fields'=>json_encode($fields,JSON_THROW_ON_ERROR),'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('inspection_form_version')+['revision'=>$revision+1];
    });}
    private function canonical(array $data): array {if(!array_is_list($data))ksort($data);foreach($data as&$value)if(is_array($value))$value=$this->canonical($value);unset($value);return $data;}
    public function submit(string $id,array $input): array {return $this->atomic(function()use($id,$input){
        $this->fields($input,['operation_uuid','answers']);$form=$this->row('inspection_form_versions','form_id',$id);$this->access->requireSite($form['site_id']);$uuid=$input['operation_uuid']??null;if(!is_string($uuid)||!preg_match('/^[a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12}$/Di',$uuid))throw HttpException::unprocessable('A stable operation UUID is required.');$answers=$input['answers']??null;if(!is_array($answers)||array_is_list($answers)||!$answers)throw HttpException::unprocessable('Inspection answers are required.');$hash=hash('sha256',json_encode([$id,$this->canonical($answers)],JSON_THROW_ON_ERROR));$keys=['company'=>$this->company(),'actor'=>$this->actor(),'uuid'=>strtolower($uuid)];$prior=$this->db->fetch('SELECT submission_id,request_hash FROM inspection_form_submissions WHERE company_id=:company AND submitted_by_user_id=:actor AND operation_uuid=:uuid',$keys);if($prior){if(!hash_equals($prior['request_hash'],$hash))throw HttpException::conflict('This operation ID was already used for different answers.');return ['id'=>(string)$prior['submission_id'],'received'=>true];}
        $latest=$this->db->fetch('SELECT form_id FROM inspection_form_versions WHERE company_id=:company AND site_id=:site AND form_code=:code ORDER BY revision DESC LIMIT 1',['company'=>$this->company(),'site'=>$form['site_id'],'code'=>$form['form_code']]);if((string)$latest['form_id']!==$id)throw HttpException::conflict('A newer inspection form is available. Reload it before submitting.');$fields=json_decode($form['fields_json'],true,512,JSON_THROW_ON_ERROR);if(array_diff(array_keys($answers),array_column($fields,'key')))throw HttpException::unprocessable('Answers include unknown fields.');$clean=[];$photos=[];$failures=[];$photoChars=0;
        foreach($fields as$f){$answer=$answers[$f['key']]??null;if($answer===null){if($f['required']||$f['photo_required'])throw HttpException::unprocessable('Complete required field: '.$f['label']);continue;}if(!is_array($answer))throw HttpException::unprocessable('Invalid field answer.');$this->fields($answer,['value','photo_base64']);$value=$answer['value']??null;
            if($f['type']==='PASS_FAIL'&&!in_array($value,['PASS','FAIL'],true))throw HttpException::unprocessable('Choose PASS or FAIL: '.$f['label']);if($f['type']==='CHECK'&&!is_bool($value))throw HttpException::unprocessable('Choose yes/no: '.$f['label']);if($f['type']==='TEXT')$value=$this->text($value,2000);if($f['type']==='NUMBER'&&((!is_int($value)&&!is_float($value))||!is_finite((float)$value)||abs($value)>1000000000))throw HttpException::unprocessable('Enter a finite number: '.$f['label']);$clean[$f['key']]=['value'=>$value];
            if(isset($answer['photo_base64'])){$b64=$answer['photo_base64'];if(!is_string($b64)||strlen($b64)>175000)throw HttpException::unprocessable('Photos must be at most 128 KiB.');$photoChars+=strlen($b64);if($photoChars>700000)throw HttpException::unprocessable('Combined inspection photos exceed the submission limit.');$bytes=base64_decode($b64,true);$size=$bytes===false?false:@getimagesizefromstring($bytes);if(!$size||!in_array($size[2],[IMAGETYPE_JPEG,IMAGETYPE_PNG],true)||strlen($bytes)>131072||$size[0]>2048||$size[1]>2048)throw HttpException::unprocessable('Use a JPEG/PNG photo up to 128 KiB and 2048 pixels per side.');$photos[$f['key']]=['base64'=>base64_encode($bytes),'hash'=>hash('sha256',$bytes),'mime'=>$size[2]===IMAGETYPE_PNG?'image/png':'image/jpeg'];$clean[$f['key']]['photo_sha256']=hash('sha256',$bytes);}elseif($f['photo_required'])throw HttpException::unprocessable('Attach the required photo: '.$f['label']);if($f['followup_on_fail']&&($value==='FAIL'||$value===false))$failures[]=$f;
        }
        $this->db->execute('INSERT INTO inspection_form_submissions(company_id,site_id,form_id,operation_uuid,request_hash,answers_json,submitted_by_user_id,submitted_at) VALUES(:company,:site,:form,:uuid,:hash,:answers,:actor,:now)',$keys+['site'=>$form['site_id'],'form'=>$id,'hash'=>$hash,'answers'=>json_encode($clean,JSON_THROW_ON_ERROR),'now'=>gmdate('Y-m-d H:i:s')]);$result=$this->created('inspection_form_submission');foreach($photos as$key=>$photo)$this->db->execute('INSERT INTO inspection_form_photos(company_id,submission_id,field_key,mime_type,image_base64,sha256) VALUES(:company,:submission,:field,:mime,:image,:hash)',['company'=>$this->company(),'submission'=>$result['id'],'field'=>$key,'mime'=>$photo['mime'],'image'=>$photo['base64'],'hash'=>$photo['hash']]);foreach($failures as$f)$this->db->execute('INSERT INTO inspection_followups(company_id,site_id,submission_id,field_key,task_name) VALUES(:company,:site,:submission,:field,:task)',['company'=>$this->company(),'site'=>$form['site_id'],'submission'=>$result['id'],'field'=>$f['key'],'task'=>'Failed check: '.$f['label']]);return $result+['received'=>true,'followups_created'=>count($failures)];
    });}
    public function history(array $input): array {$this->fields($input,['site_id']);$site=$this->access->requireSite($input['site_id']??null);$result=['submissions'=>$this->db->fetchAll('SELECT s.submission_id,s.form_id,f.form_code,f.revision,s.answers_json,s.submitted_by_user_id,s.submitted_at FROM inspection_form_submissions s JOIN inspection_form_versions f ON f.company_id=s.company_id AND f.form_id=s.form_id WHERE s.company_id=:company AND s.site_id=:site ORDER BY s.submission_id DESC LIMIT 200',['company'=>$this->company(),'site'=>$site['site_id']]),'followups'=>$this->db->fetchAll('SELECT * FROM inspection_followups WHERE company_id=:company AND site_id=:site ORDER BY followup_id DESC LIMIT 300',['company'=>$this->company(),'site'=>$site['site_id']])];foreach($result['submissions']as&$submission)$submission['photos']=$this->db->fetchAll('SELECT photo_id,field_key,mime_type,sha256 FROM inspection_form_photos WHERE company_id=:company AND submission_id=:id',['company'=>$this->company(),'id'=>$submission['submission_id']]);unset($submission);return $result;}
    public function photo(string $id): array {$photo=$this->row('inspection_form_photos','photo_id',$id);$submission=$this->row('inspection_form_submissions','submission_id',$photo['submission_id']);$this->access->requireSite($submission['site_id']);$bytes=base64_decode($photo['image_base64'],true);if($bytes===false||!hash_equals($photo['sha256'],hash('sha256',$bytes)))throw HttpException::conflict('Inspection photo failed integrity verification.');$this->audit->record('inspection_form_photo','viewed',$id);return ['bytes'=>$bytes,'mime'=>$photo['mime_type']];}
    public function resolve(string $id,array $input): array {return $this->atomic(function()use($id,$input){$this->fields($input,['resolution']);$row=$this->row('inspection_followups','followup_id',$id);$this->access->requireSite($row['site_id']);if($row['state']!=='OPEN')throw HttpException::conflict('Follow-up already resolved.');$this->db->execute("UPDATE inspection_followups SET state='RESOLVED',resolution=:resolution,resolved_by_user_id=:actor,resolved_at=:now WHERE company_id=:company AND followup_id=:id",['resolution'=>$this->text($input['resolution']??null,1000),'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$id]);$this->audit->record('inspection_followup','resolved',$id);return ['resolved'=>true];});}
}
